def _compile_code(code_str, name, env=None, verbose=False):
    if env is None:
        env = {}
    try:
        code = compile(code_str, '<cli>', 'exec')
        exec(code, env)
        return env[name]
    except Exception as e:
        raise UsageError(f'could not evaluate spec, got: {e.__class__.__name__}: {e}')
